"""Regenerate src/lib/seo-noindex-list.ts from the spec sheet's Metadata tab.

Every row whose Status is "noindex" becomes one entry.
Usage: python3 -I scripts/seo/gen-noindex.py /seo-data/metadata-all-pages.csv
"""
import csv
import sys

rows = [r for r in csv.DictReader(open(sys.argv[1], encoding='utf-8')) if r['Status'] == 'noindex']
lines = [
    '// GENERATED by scripts/seo/gen-noindex.py from the SEO spec sheet,',
    '// tab "Metadata (all pages)", every row with Status = "noindex".',
    '// Edit the sheet and regenerate rather than editing this by hand.',
    '',
    'export const SHEET_NOINDEX_PATHS: readonly string[] = [',
]
for r in rows:
    lines.append(f"  '{r['URL']}', // {r['Page type']}")
lines.append(']')
open('src/lib/seo-noindex-list.ts', 'w', encoding='utf-8').write('\n'.join(lines) + '\n')
print(f'{len(rows)} noindex paths written')
